import {ArrowDownIcon, ArrowUpIcon, PulseIcon} from '@primer/octicons-react'
import {Spinner} from '@primer/react'
import {Octicon} from '@primer/react/deprecated'
import {clsx} from 'clsx'

import styles from './TrendIndicator.module.css'

type Props = {
  loading: boolean
  error: boolean
  value?: number
  flipColor?: boolean
  className?: string
  maxValue?: number
  metric?: string
}

export function TrendIndicator({
  loading,
  error,
  value,
  flipColor = false,
  className,
  maxValue = 999,
  metric = '%',
}: Props): React.ReactElement {
  if (error) {
    return <></>
  }

  if (loading || value === undefined) {
    return <Spinner data-testid="trend-indicator-spinner" size="small" className={clsx(styles.Spinner, className)} />
  }

  let color = 'var(--fgColor-muted)'
  let icon = PulseIcon
  if (value > 0) {
    color = flipColor ? 'var(--fgColor-success)' : 'var(--fgColor-closed)'
    icon = ArrowUpIcon
  } else if (value < 0) {
    color = flipColor ? 'var(--fgColor-closed)' : 'var(--fgColor-success)'
    icon = ArrowDownIcon
  }

  return (
    <div className={clsx('text-small', styles.Box, className)} style={{color}}>
      <Octicon icon={icon} />{' '}
      <span data-testid="trend-indicator-value">
        {value > maxValue ? `${maxValue}${metric}+` : `${value}${metric}`}
      </span>
    </div>
  )
}
